{
  "outcome": "deny",
  "rationale": "We are denying this claim because the claimant admitted to installing an unreported turbo kit and exhaust, which triggers the aftermarket modifications exclusion. This loss is governed by Section 4, Exclusions, which excludes coverage for non-factory performance modifications. The key fact is that these modifications were never declared or endorsed on the policy.",
  "citations": [
    {
      "clause_id": "BASIC-4.8",
      "quote": "We do not cover loss to, or loss caused by, non-factory modifications to the covered vehicle that change its performance, including engine, turbo, exhaust and suspension modifications, unless the modification was declared to us and endorsed on this policy."
    }
  ]
}
